/**
 * Optimizes image URLs for modern format delivery and sizing.
 * For Unsplash images (powered by imgix), appends auto=format for WebP/AVIF
 * and resizing parameters. Non-Unsplash URLs are returned unchanged.
 */
export function optimizeImageUrl(url: string, width: number = 800): string {
  if (!url) return url;

  // Only optimize Unsplash URLs (powered by imgix)
  if (url.includes('images.unsplash.com')) {
    const separator = url.includes('?') ? '&' : '?';
    return `${url}${separator}auto=format&w=${width}&q=80`;
  }

  // Supabase storage and other URLs returned as-is
  return url;
}
